function openCmd(){if(!role)return;closeCmd();const c=document.createElement('div');c.id='cmd';c.innerHTML='<div class="cbox" role="dialog" aria-label="Quick search"><input id="cq" placeholder="Search pages, crops, activities, guide…  (Esc to close)" aria-label="Quick search" autocomplete="off"><div id="cres"></div></div>';document.body.appendChild(c);c.onclick=e=>{if(e.target==c)closeCmd()};const q=c.querySelector('#cq');q.oninput=()=>cmdRes(q.value);q.onkeydown=e=>{if(e.key=='Enter'){const f=document.querySelector('#cres button');if(f)f.click()}};cmdRes('');q.focus()}
function closeCmd(){const c=document.getElementById('cmd');if(c)c.remove()}
function cmdRes(v){const q=v.trim().toLowerCase(),R=[];navFor().forEach(n=>R.push(['Page',n[1],`go('${n[0]}')`]));S.crops.forEach(c=>R.push(['Crop',c.name,`go('crops')`]));GD.forEach(g=>R.push(['Guide',g.n+' ('+g.l+')',`gs('${g.k}');go('guide')`]));S.tasks.filter(t=>!t.done).slice(0,80).forEach(t=>R.push(['Activity',t.type+' · '+cn(t.crop).name+' · '+fmt(t.date),`openTask(${t.id})`]));
const m=R.filter(r=>!q||r[1].toLowerCase().includes(q)||r[0].toLowerCase().includes(q)).slice(0,9);document.getElementById('cres').innerHTML=m.length?m.map(r=>`<button onclick="closeCmd();${r[2]}"><span class="tag">${r[0]}</span>${r[1]}</button>`).join(''):'<div class="empty">No results</div>'}
