const WX={asOf:'2026-10-30',loc:'San Carlos City, Pangasinan',now:{f:87.6,txt:'Light rain'},d:[['2026-10-30',92.8,77.9,65],['2026-10-31',92.4,78.3,25],['2026-11-01',88.3,77.0,45],['2026-11-02',93.3,78.0,15],['2026-11-03',91.7,76.4,15],['2026-11-04',91.2,75.3,15],['2026-11-05',91.1,74.9,10],['2026-11-06',91.4,75.5,5]]};
const C=f=>Math.round((f-32)*5/9);
const wxDay=d=>{if(!wxLive&&wxFar())return null;const x=WX.d.find(a=>a[0]==d);return x?{date:x[0],hi:C(x[1]),lo:C(x[2]),pop:x[3],wind:x[4]}:null};
const wxTxt=p=>p>=80?'Rain':p>=60?'Likely rain':p>=40?'Chance of rain':p>=20?'Slight chance of rain':'Mostly dry';
function wxIcon(p,s=36){const sun='<circle cx="12" cy="12" r="4.5" fill="#e9a41a" stroke="none"/><path d="M12 2v2.5M12 19.5V22M2 12h2.5M19.5 12H22M4.9 4.9l1.8 1.8M17.3 17.3l1.8 1.8M19.1 4.9l-1.8 1.8M6.7 17.3l-1.8 1.8" stroke="#e9a41a"/>',cl='<path d="M7 18a4.5 4.5 0 01-.6-8.97A6 6 0 0118 10.5 3.75 3.75 0 0117.25 18z" fill="#cfdbe0" stroke="#7f9aa6"/>',rain='<path d="M8 20l-1 2M12 20l-1 2M16 20l-1 2" stroke="#2a86d1"/>';
return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p<20?sun:p<40?'<g transform="translate(-3 -3) scale(.7)">'+sun+'</g><g transform="translate(2 3) scale(.85)">'+cl+'</g>':p<60?cl:cl+rain}</svg>`}
const ADV={Planting:w=>w.pop>=70?['no','Heavy rain is likely and can wash away seeds and seedlings. Wait for a drier day.']:w.pop>=50?['warn','Rain is possible. Plant in the morning or wait for a drier day.']:w.hi>=36?['warn','It will be very hot. Plant early in the morning or late afternoon.']:['ok','Good conditions for planting.'],
Fertilizing:w=>w.pop>=60?['no','Rain can wash fertilizer away. Delay the application.']:w.pop>=40?['warn','Some rain is possible. Apply early and skip it if clouds build up.']:['ok','Good day to fertilize.'],
'Pest control':w=>(w.wind||0)>=30?['no','Strong wind will blow the spray away. Delay spraying.']:w.pop>=50?['no','Rain will wash off the spray. Delay spraying.']:w.pop>=30?['warn','Chance of rain. Spray early in the morning.']:['ok','Good day to spray.'],
Harvesting:w=>w.pop>=50?['no','Rain can damage the harvest and slow drying. Harvest on a drier day.']:w.pop>=30?['warn','Chance of rain. Harvest early and keep covers ready.']:['ok','Good day to harvest.'],
Watering:w=>w.pop>=60?['info','Rain is expected. You may skip watering.']:w.hi>=35?['ok','Hot day. Water early in the morning or in the evening.']:['ok','Water as scheduled.'],
Weeding:w=>w.pop>=70?['warn','Wet soil makes weeding hard.']:['ok','Good day for weeding.'],Pruning:w=>w.pop>=60?['warn','Wet cuts can invite disease. Prune on a dry day.']:['ok','Good day to prune.'],Inspection:w=>['ok','Good day to inspect your crops.']};
const wxAdv=(type,date)=>{const w=wxDay(date);return w&&ADV[type]?ADV[type](w):null};
function wxAlerts(){return S.tasks.filter(t=>!t.done&&t.date>=TODAY&&wxDay(t.date)).map(t=>({t,a:wxAdv(t.type,t.date)})).filter(x=>x.a&&(x.a[0]=='no'||x.a[0]=='warn')).map(x=>({id:x.t.id,lvl:x.a[0],msg:x.t.type+' · '+cn(x.t.crop).name+' on '+fmt(x.t.date)+': '+x.a[1]}))}
function wxTag(t){const a=!t.done&&t.date>=TODAY?wxAdv(t.type,t.date):null;return a&&a[0]=='no'?`<span class="tag late" title="${a[1]}">Weather risk</span>`:a&&a[0]=='warn'?`<span class="tag warn" title="${a[1]}">Check weather</span>`:''}
function wxMove(id){const t=S.tasks.find(x=>x.id==id),n=WX.d.map(x=>x[0]).filter(d=>d>t.date&&d>=TODAY).find(d=>{const a=wxAdv(t.type,d);return a&&(a[0]=='ok'||a[0]=='info')});if(!n){toast('No better day found in this forecast.');return}t.date=n;save();toast('Moved to '+fmt(n,{weekday:'long',month:'short',day:'numeric'}));render()}
function wxCard(){const w=wxDay(TODAY);if(!w)return `<div class="card"><h2>Weather and planting advisory</h2><p class="ts">${wxMsg()}</p></div>`;
return `<div class="card"><h2>Weather and planting advisory <button class="btn ghost sm" onclick="go('weather')">Full forecast</button></h2><div class="wxnow">${wxIcon(w.pop,56)}<div><b style="font-size:34px;letter-spacing:-.04em">${w.hi}°C</b><div class="ts">${wxTxt(w.pop)} · ${w.pop}% chance of rain · low ${w.lo}°C</div></div></div>${['Planting','Fertilizing','Pest control','Harvesting'].map(k=>{const a=ADV[k](w);return `<div class="adv ${a[0]}"><b>${k}</b><span>${a[1]}</span></div>`}).join('')}<p class="ts" style="margin:12px 0 0">${WX.loc}. ${wxLive?'Live forecast, updated '+WX.stamp+'.':'Forecast saved '+fmt(WX.asOf,{month:'short',day:'numeric',year:'numeric'})+'.'}</p></div>`}
V.weather=function(){const days=WX.d.filter(x=>x[0]>=TODAY),w0=wxDay(TODAY),al=wxAlerts();
const rows=['Planting','Fertilizing','Pest control','Harvesting','Watering'];
return `<div class="top"><div><h1>Weather and planting advisory</h1><p>${WX.loc}. Plan planting, spraying, and harvest around the forecast.</p></div><span style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">${wxBadge()}</span></div>
${locCard()}
${days.length?`<div class="card" style="margin-bottom:16px"><div class="wxnow" style="margin:0">${wxIcon(w0?w0.pop:0,64)}<div><div class="ts">Today</div><b style="font-size:40px;letter-spacing:-.04em">${w0?w0.hi+'°C':'–'}</b><div class="ts">Right now: ${C(WX.now.f)}°C${WX.now.txt?', '+WX.now.txt.toLowerCase():''}</div><div class="ts">${w0?wxTxt(w0.pop)+' · '+w0.pop+'% chance of rain · low '+w0.lo+'°C':''}</div></div></div></div>
<div class="wxs">${days.map((x,i)=>{const w=wxDay(x[0]);return `<div class="wxd ${i==0?'today':''}"><b>${i==0?'Today':fmt(x[0],{weekday:'short'})}</b><div class="ts">${fmt(x[0])}</div>${wxIcon(w.pop,40)}<div><b>${w.hi}°</b> <span class="ts">${w.lo}°</span></div><div class="pb"><i style="width:${w.pop}%"></i></div><div class="ts">${w.pop}% rain</div>${w.wind!=null?`<div class="ts">${Math.round(w.wind)} km/h wind</div>`:''}</div>`}).join('')}</div>
<div class="card scroll" style="margin-top:16px"><h2>Best days for each activity</h2><table><thead><tr><th>Activity</th>${days.slice(0,7).map(x=>`<th style="text-align:center">${fmt(x[0],{weekday:'short'})}<br>${fmt(x[0],{day:'numeric'})}</th>`).join('')}</tr></thead><tbody>${rows.map(k=>`<tr><td><b>${k}</b></td>${days.slice(0,7).map(x=>{const a=ADV[k](wxDay(x[0]));return `<td style="text-align:center"><span class="dotc ${a[0]}" title="${a[1]}" role="img" aria-label="${k}, ${fmt(x[0])}: ${a[1]}"></span></td>`}).join('')}</tr>`).join('')}</tbody></table>
<div class="legend"><span><i class="dotc ok" style="width:12px;height:12px;border-radius:4px;vertical-align:middle"></i> Good day</span><span><i class="dotc warn" style="width:12px;height:12px;border-radius:4px;vertical-align:middle"></i> Be careful</span><span><i class="dotc no" style="width:12px;height:12px;border-radius:4px;vertical-align:middle"></i> Not advised</span><span><i class="dotc info" style="width:12px;height:12px;border-radius:4px;vertical-align:middle"></i> Can skip</span></div></div>
<div class="card" style="margin-top:16px"><h2>Your scheduled activities and the weather</h2>${al.length?al.map(x=>{const t=S.tasks.find(y=>y.id==x.id);return `<div class="adv ${x.lvl}" style="align-items:center"><span style="flex:1">${x.msg}</span><button class="btn ghost sm" onclick="wxMove(${x.id})">Move to a better day</button></div>`}).join(''):'<div class="empty">No scheduled activity is affected by the forecast.</div>'}</div>`:`<div class="card empty">${wxMsg()}</div>`}
<div class="card" style="margin-top:16px;background:var(--soft)"><h2 style="margin-bottom:6px">About this forecast</h2><p class="ts" style="margin:0">${wxLive?`This is a live forecast for ${WX.loc}, refreshed every 30 minutes while the page is open. Weather data by <a href="https://open-meteo.com" target="_blank" rel="noopener">Open-Meteo</a>.`:`This is a saved forecast for ${WX.loc} (${fmt(WX.asOf,{month:'long',day:'numeric',year:'numeric'})}), not a live feed.`} The advice is based on rain chance and temperature, and it can change. Always check official PAGASA bulletins and your local DRRMO for typhoon, flood, and rainfall warnings before planting or spraying. ${wxLive?'':'When the system is hosted on its own web server, this updates automatically.'}</p></div>`};
function banners(){let h='';const w=wxAlerts().filter(x=>x.lvl=='no');if(w.length)h+=`<div class="ban late" role="alert"><b>Weather alert</b><span>${w.length} scheduled ${w.length==1?'activity is':'activities are'} not advised because of rain. ${esc(w[0].msg)}</span><button class="btn sm" onclick="go('weather')">Review</button></div>`;
const a=(S.ann||[])[0];if(a&&!window._annX)h+=`<div class="ban info"><b>Announcement</b><span>${esc(a.text)}</span><button class="btn ghost sm" onclick="window._annX=1;render()">Dismiss</button></div>`;return h}
/* ---------- accounts, roles, admin ---------- */
const ACC=[{u:'juan',p:'farmer123',n:'Juan dela Cruz',r:'Farmer'},{u:'admin',p:'admin123',n:'Administrator',r:'Admin'}];
const accounts=()=>[...ACC,...(S.users||[])];
const ANAV=[['admin','Overview'],['weather','Weather'],['reports','Reports'],['guide','Guide']];
const navFor=()=>role=='Admin'?ANAV:NAV.filter(n=>n[0]!='admin');
function enter(a){role=a.r;UN=a.r=='Admin'?'Admin':a.n.split(' ')[0];UI=a.n.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();window._annX=0;location.hash='dashboard';render();window.scrollTo(0,0);if(S.loc&&S.loc.mode=='gps')detectLoc(false)}
function doLogin(){const u=($('#lu').value||'').trim().toLowerCase(),p=$('#lp').value,a=accounts().find(x=>x.u==u&&x.p==p);if(!a){$('#lerr').textContent='Incorrect username or password. Please try again.';return}enter(a)}
function doSignup(){const n=$('#sn').value.trim(),u=$('#su').value.trim().toLowerCase(),p=$('#sp').value,e=$('#lerr');if(!n){e.textContent='Please enter your full name.';return}if(!/^[a-z0-9._]{3,}$/.test(u)){e.textContent='Username must be at least 3 letters or numbers.';return}if(accounts().some(x=>x.u==u)){e.textContent='That username is already taken.';return}if(p.length<6){e.textContent='Password must be at least 6 characters.';return}const a={u,p,n,r:'Farmer'};S.users=S.users||[];S.users.push(a);save();enter(a)}
function showPw(){const i=$('#lp')||$('#sp');i.type=i.type=='password'?'text':'password'}
function postAnn(){const t=$('#annt').value.trim();if(!t){toast('Write the announcement first');return}S.ann.unshift({id:S.nid++,text:t,date:TODAY});save();window._annX=0;toast('Announcement posted');render()}
V.admin=function(){const U=[['Juan dela Cruz','juan','Active'],['Maria Santos','msantos','Active'],['Pedro Reyes','preyes','Pending'],...(S.users||[]).map(u=>[u.n,u.u,'Active'])];
return `<div class="top"><div><h1>Association overview</h1><p>Farmers, announcements, and the weather outlook for Barangay Magtaking.</p></div></div>
${banners()}<div class="grid g4" style="margin-bottom:16px"><div class="card kpi"><small>Registered farmers</small><b>${U.length}</b></div><div class="card kpi"><small>Crops tracked</small><b>${S.crops.length}</b></div><div class="card kpi"><small>Activities</small><b>${S.tasks.length}</b></div><div class="card kpi"><small>Completion rate</small><b>${rate(S.tasks.filter(t=>t.date<=TODAY))}%</b></div></div>
<div class="grid g2"><div class="card"><h2>Announcements</h2><label for="annt" class="ts" style="font-weight:700">Message to all farmers</label><textarea id="annt" rows="3" placeholder="e.g. Seed distribution on Monday at the barangay hall"></textarea><button class="btn gold" style="margin-top:10px" onclick="postAnn()">Post announcement</button><div style="margin-top:14px">${(S.ann||[]).map(a=>`<div class="task"><div><div class="tt" style="cursor:default">${esc(a.text)}</div><div class="ts">${fmt(a.date,{month:'long',day:'numeric'})}</div></div><button class="btn red sm tg" aria-label="Remove announcement" onclick="rm('ann',${a.id})">✕</button></div>`).join('')||'<div class="empty">No announcements.</div>'}</div></div>${wxCard()}</div>
<div class="card scroll" style="margin-top:16px"><h2>Farmer accounts</h2><table><thead><tr><th>Name</th><th>Username</th><th>Status</th></tr></thead><tbody>${U.map(u=>`<tr><td><b>${esc(u[0])}</b></td><td>${esc(u[1])}</td><td><span class="tag ${u[2]=='Active'?'ok':'warn'}">${u[2]}</span></td></tr>`).join('')}</tbody></table><p class="ts" style="margin:14px 0 0">Sample accounts for the prototype.</p><button class="btn ghost sm" style="margin-top:10px" onclick="S=seed();fix();save();render();toast('Sample data restored')">Reset sample data</button></div>`};
/* ---------- login and hero scenes ---------- */
function field(sc){let s=`<defs><linearGradient id="gFld" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a8cf72"/><stop offset="1" stop-color="#4f8a35"/></linearGradient></defs>`;return s}
function heroScene(){let s=ADEFS+`<defs><linearGradient id="gFld" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b3d57b"/><stop offset="1" stop-color="#4f8a35"/></linearGradient><radialGradient id="gSun"><stop offset="0" stop-color="#ffd98a" stop-opacity=".9"/><stop offset="1" stop-color="#ffd98a" stop-opacity="0"/></radialGradient></defs><circle cx="1180" cy="190" r="240" fill="url(#gSun)"/><circle cx="1180" cy="190" r="50" fill="#ffe6a8"/>
<g style="fill:#fff" opacity=".9"><g class="cloud" style="animation-delay:-25s"><ellipse cx="0" cy="130" rx="70" ry="22"/><ellipse cx="40" cy="115" rx="45" ry="24"/><ellipse cx="-35" cy="118" rx="38" ry="20"/></g><g class="cloud" style="animation-duration:140s;animation-delay:-90s"><ellipse cx="0" cy="250" rx="90" ry="26"/><ellipse cx="50" cy="232" rx="55" ry="28"/></g></g>
<path d="M0 560L150 480 290 545 460 440 640 535 820 455 1010 540 1190 470 1440 545V820H0Z" fill="#8fb0a0" opacity=".45"/><path d="M0 610L200 545 380 595 600 525 860 595 1100 535 1440 605V820H0Z" fill="#7aa58a" opacity=".55"/><rect y="600" width="1440" height="240" fill="url(#gFld)"/>
<g stroke="#fff" stroke-width="2" opacity=".16">${[...Array(25)].map((_,i)=>`<path d="M${720+(i-12)*16} 600L${720+(i-12)*140} 830"/>`).join('')}</g>`;
[[70,1.5],[250,1.9],[440,1.45],[640,2],[840,1.5],[1030,1.95],[1220,1.5],[1390,1.8]].forEach(([x,sc],i)=>{s+=`<g transform="translate(${x-70*sc} ${(832-147*sc).toFixed(0)}) scale(${sc})"><g class="sway" style="animation-delay:-${(i*.7).toFixed(1)}s">${artG('rice',4)}</g></g>`});return s}
function lgScene(){let s=ADEFS+`<defs><linearGradient id="gSky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#27553a"/><stop offset=".55" stop-color="#6f9b55"/><stop offset="1" stop-color="#f2c56c"/></linearGradient><linearGradient id="gFld2" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9cc060"/><stop offset="1" stop-color="#3d7230"/></linearGradient><radialGradient id="gSun2"><stop offset="0" stop-color="#fff0b8" stop-opacity=".95"/><stop offset="1" stop-color="#ffd98a" stop-opacity="0"/></radialGradient></defs><rect width="520" height="680" fill="url(#gSky)"/><circle cx="330" cy="440" r="180" fill="url(#gSun2)"/><circle cx="330" cy="440" r="42" fill="#fff3c4"/>
<path d="M0 470L90 420 180 462 290 400 400 458 520 415V680H0Z" fill="#2f5d44" opacity=".55"/><rect y="470" width="520" height="220" fill="url(#gFld2)"/><g stroke="#fff" stroke-width="1.5" opacity=".15">${[...Array(18)].map((_,i)=>`<path d="M${260+(i-9)*10} 470L${260+(i-9)*95} 690"/>`).join('')}</g>`;
[[40,2.1],[190,2.5],[350,2.1],[490,2.6]].forEach(([x,sc],i)=>{s+=`<g transform="translate(${x-70*sc} ${(692-147*sc).toFixed(0)}) scale(${sc})"><g class="sway" style="animation-delay:-${(i*.9).toFixed(1)}s">${artG('rice',4)}</g></g>`});return s}
function authView2(m){const up=m=='signup';return `<div class="lg"><div class="lgcard"><div class="lgl"><svg class="lgs" viewBox="0 0 520 680" preserveAspectRatio="xMidYMax slice" aria-hidden="true">${lgScene()}</svg><div class="lgtxt"><div class="lgbrand">${LOGO}<b>Crop Care Scheduler</b></div><h1>${up?'Start planning your season.':'Every task, on schedule.'}</h1><p>Farm activity scheduling and completion monitoring for the farmers of Barangay Magtaking.</p></div></div>
<div class="lgr"><svg class="wave" viewBox="0 0 80 600" preserveAspectRatio="none" aria-hidden="true"><path d="M80 0H0C34 90 -6 190 26 300S60 480 0 600H80Z" fill="var(--surf)"/></svg><div class="lgf"><button class="lgback" onclick="go2('landing')">← Back to home</button><h2>${up?'Create your account':'Sign in'}</h2><p class="ts" style="margin:0 0 6px">${up?'Set up your farm account to start scheduling.':'Enter your username and password.'}</p>
${up?`<label for="sn">Full name</label><input id="sn" placeholder="Juan dela Cruz" autocomplete="name"><label for="su">Username</label><input id="su" placeholder="juan.delacruz" autocomplete="username">`:`<label for="lu">Username</label><input id="lu" placeholder="Your username" autocomplete="username">`}
<label for="${up?'sp':'lp'}">Password</label><div class="pw"><input id="${up?'sp':'lp'}" type="password" placeholder="${up?'At least 6 characters':'Your password'}" autocomplete="${up?'new-password':'current-password'}"><button type="button" onclick="showPw()" aria-label="Show or hide password">${svg('M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12zM12 15a3 3 0 100-6 3 3 0 000 6z',18)}</button></div>
<div id="lerr" class="lerr" role="alert"></div><button type="button" class="btn gold lgbtn" onclick="${up?'doSignup()':'doLogin()'}">${up?'Create account':'Sign in'}</button>
<p class="ts" style="text-align:center;margin:16px 0 0">${up?'Already have an account? <a href="#" onclick="event.preventDefault();go2(\'login\')">Sign in</a>':'New here? <a href="#" onclick="event.preventDefault();go2(\'signup\')">Create an account</a>'}</p>
${up?'':'<details class="demo"><summary>Demo accounts for testing</summary><p>Farmer: <b>juan</b> / <b>farmer123</b><br>Administrator: <b>admin</b> / <b>admin123</b></p></details>'}</div></div></div></div>`}
/* ---------- terms ---------- */
const TERMS={terms:[['1. About the system','Crop Care Scheduler is a capstone project of Binalatongan Community College students for the farmers of Barangay Magtaking, San Carlos City, Pangasinan. It helps you plan farm activities, monitor whether they are done, and keep farm records.'],['2. Your account','Keep your username and password to yourself. You are responsible for what is done with your account. Give correct information and keep your records honest.'],['3. Proper use','Do not use the system for anything unlawful, do not enter false records, and do not try to open another person’s account or data.'],['4. Guides and forecasts','The planting guide, care plans, and weather advice are general information. They do not replace the advice of the Municipal Agriculture Office, the Department of Agriculture, or PAGASA.'],['5. Availability','This is a prototype. It may change, be slow, or be unavailable. Keep your own copy of important records.'],['6. Changes','These terms may be updated. Continuing to use the system means you accept the updated terms.']],
priv:[['Law followed','This notice is based on the Data Privacy Act of 2012 (Republic Act No. 10173).'],['What we collect','Your name, username, and the farm records you enter: crops, activities, observations, harvests, expenses, inventory, and workers. If you allow it, your device location is used to show the weather where you are, and it is saved only in your browser.'],['Why we collect it','To schedule your farm activities, show your progress, give reminders and advisories, and produce reports for you and for authorized association administrators.'],['Where it is kept','In this prototype, your records are saved in your own browser on this device. A full version would keep them on a secured server.'],['Who can see it','You, and association administrators who need it to support farmers. Your data is not sold or shared for advertising.'],['Your rights','You may ask to see, correct, or delete your information, and you may object to its use. Contact the project team or the association office.'],['Security','Use a password only you know. No system is perfectly secure, so avoid entering sensitive personal details such as bank or ATM numbers.']],
disc:[['Weather advice','The weather shown is a saved forecast, not a live feed. Rain chances change, so check PAGASA and your local DRRMO for typhoon, flood, and rainfall warnings before planting, spraying, or harvesting.'],['Planting guide','Planting months, spacing, and growing steps are general and based on common practice in Luzon. Your best dates depend on rainfall, irrigation, soil, and variety.'],['Decisions are yours','The system gives suggestions only. You decide what to do on your farm, and the developers are not responsible for crop losses that follow from these suggestions.']]};
function showTerms(view){closeTerms();const d=document.createElement('div');d.id='tm';d.innerHTML=`<div class="tmb" role="dialog" aria-modal="true" aria-label="Terms and notices"><div class="tmh"><div class="lgbrand dk">${LOGO}<b>Crop Care Scheduler</b></div><h2 style="display:block;font-size:24px;margin:14px 0 2px">${view?'Terms and notices':'Before you continue'}</h2><p class="ts" style="margin:0">${view?'You can review these at any time.':'Please read and accept these to use the system.'}</p></div><div class="tmt">${[['terms','Terms of Use'],['priv','Data Privacy'],['disc','Advisory notice']].map(x=>`<button data-t="${x[0]}">${x[1]}</button>`).join('')}</div><div class="tmc" id="tmc"></div><div class="tmf">${view?'<button class="btn gold" id="tmok">Close</button>':`<label class="chkl"><input type="checkbox" id="tmchk"> I have read and agree to the Terms of Use and the Data Privacy Notice.</label><div style="display:flex;gap:10px;justify-content:flex-end;margin-top:12px"><button class="btn ghost" id="tmno">Decline</button><button class="btn gold" id="tmok" disabled>Accept and continue</button></div>`}</div></div>`;document.body.appendChild(d);
const fill=k=>{$('#tmc').innerHTML=TERMS[k].map(a=>`<h4>${a[0]}</h4><p style="margin:0;color:var(--mute)">${a[1]}</p>`).join('');d.querySelectorAll('.tmt button').forEach(b=>b.classList.toggle('on',b.dataset.t==k));$('#tmc').scrollTop=0};fill('terms');d.querySelectorAll('.tmt button').forEach(b=>b.onclick=()=>fill(b.dataset.t));$('#tmok').onclick=closeTerms;
if(!view){const c=$('#tmchk');c.onchange=()=>{$('#tmok').disabled=!c.checked};$('#tmno').onclick=()=>toast('You need to accept the terms to use Crop Care Scheduler.',3200)}}
function closeTerms(){const d=document.getElementById('tm');if(d)d.remove()}
setTimeout(()=>showTerms(false),matchMedia('(prefers-reduced-motion:reduce)').matches?300:1700);

const DEF={lat:15.9289,lon:120.3487,name:'San Carlos City, Pangasinan',mode:'default'};
let LOC=Object.assign({},DEF,S.loc||{});WX.loc=LOC.name;
const kmBetween=(a,b,c,d)=>{const r=Math.PI/180,x=(c-a)*r,y=(d-b)*r,h=Math.sin(x/2)**2+Math.cos(a*r)*Math.cos(c*r)*Math.sin(y/2)**2;return 12742*Math.asin(Math.sqrt(h))};
const wxFar=()=>kmBetween(LOC.lat,LOC.lon,DEF.lat,DEF.lon)>15;
const wxMsg=()=>wxFar()&&!wxLive?'Weather for your exact location needs an internet connection. The saved forecast covers San Carlos City only.':'The saved forecast has expired. Connect to the internet for live weather, and check PAGASA for current conditions.';
function locMsg(m){const e=document.getElementById('locmsg');if(e)e.textContent=m}
async function placeName(lat,lon){try{const r=await fetch('https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=14&accept-language=en&lat='+lat+'&lon='+lon),j=await r.json(),a=j.address||{};return [a.village||a.suburb||a.hamlet||a.neighbourhood||a.city_district,a.city||a.town||a.municipality||a.county,a.state].filter((x,i,ar)=>x&&ar.indexOf(x)==i).slice(0,3).join(', ')}catch(e){return ''}}
function detectLoc(manual){if(!navigator.geolocation){locMsg('This browser does not support location.');return}locMsg('Finding your location…');
navigator.geolocation.getCurrentPosition(async p=>{const lat=p.coords.latitude,lon=p.coords.longitude;LOC={lat,lon,acc:Math.round(p.coords.accuracy),name:lat.toFixed(3)+', '+lon.toFixed(3),mode:'gps'};const n=await placeName(lat,lon);if(n)LOC.name=n;WX.loc=LOC.name;S.loc=LOC;save();locMsg('');await loadWx(false);if(manual)toast('Using your location');render()},
err=>{locMsg(err.code==1?'Location access is blocked. Allow location for this site in your browser settings, then try again.':err.code==3?'Finding your location took too long. Move to an open area and try again.':'Could not find your location.')},{enableHighAccuracy:true,timeout:15000,maximumAge:60000})}
function useDefault(){LOC=Object.assign({},DEF);WX.loc=LOC.name;S.loc=LOC;save();loadWx(false);render()}
function locCard(){const b=.03,map='https://www.openstreetmap.org/export/embed.html?bbox='+(LOC.lon-b).toFixed(4)+'%2C'+(LOC.lat-b*.6).toFixed(4)+'%2C'+(LOC.lon+b).toFixed(4)+'%2C'+(LOC.lat+b*.6).toFixed(4)+'&layer=mapnik&marker='+LOC.lat.toFixed(5)+'%2C'+LOC.lon.toFixed(5);
return `<div class="card loc" style="margin-bottom:16px"><div class="locmap"><div class="locfb">${svg('M12 21s-7-6.2-7-11a7 7 0 0114 0c0 4.8-7 11-7 11zM12 12a2.5 2.5 0 100-5 2.5 2.5 0 000 5z',34)}<span>The map appears when you are online</span></div><iframe title="Map of your location" src="${map}" loading="lazy" referrerpolicy="no-referrer"></iframe></div>
<div class="locinfo"><div class="eyebrow mono">${LOC.mode=='gps'?'YOUR LOCATION (GPS)':'DEFAULT LOCATION'}</div><h2 style="display:block;margin:4px 0 8px;font-size:22px">${esc(LOC.name)}</h2><div class="ts">${LOC.lat.toFixed(4)}°N, ${LOC.lon.toFixed(4)}°E${LOC.acc?' · accurate to about '+LOC.acc+' m':''}</div>
<div style="display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 6px"><button class="btn gold" onclick="detectLoc(true)">${svg('M12 2v3M12 19v3M2 12h3M19 12h3M12 17a5 5 0 100-10 5 5 0 000 10z',16)} Use my GPS location</button>${LOC.mode=='gps'?'<button class="btn ghost" onclick="useDefault()">Use default (San Carlos City)</button>':''}</div><div id="locmsg" class="ts" role="status"></div>
<p class="ts" style="margin:10px 0 0">The forecast is for these coordinates. Weather models cover areas of several kilometers, so they cannot measure rain on one exact farm. <a href="https://www.openstreetmap.org/?mlat=${LOC.lat}&mlon=${LOC.lon}#map=14/${LOC.lat}/${LOC.lon}" target="_blank" rel="noopener">Open larger map</a></p></div></div>`}
let wxLive=false;
function wxBadge(){return wxLive?`<span class="tag ok">● Live · updated ${WX.stamp}</span> <button class="btn ghost sm" onclick="loadWx(1)">Refresh</button>`:`<span class="tag warn">Forecast as of ${fmt(WX.asOf,{month:'short',day:'numeric'})}</span>`}
async function loadWx(manual){try{const u='https://api.open-meteo.com/v1/forecast?latitude='+LOC.lat.toFixed(4)+'&longitude='+LOC.lon.toFixed(4)+'&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,wind_speed_10m_max&current=temperature_2m&timezone=Asia%2FManila&forecast_days=8',r=await fetch(u);if(!r.ok)throw new Error('http');const j=await r.json(),d=j.daily;if(!d||!d.time||!d.time.length)throw new Error('empty');
WX.d=d.time.map((t,i)=>[t,d.temperature_2m_max[i]*9/5+32,d.temperature_2m_min[i]*9/5+32,d.precipitation_probability_max[i]==null?0:d.precipitation_probability_max[i],d.wind_speed_10m_max[i]]);WX.now={f:j.current.temperature_2m*9/5+32};WX.asOf=iso(new Date());WX.loc=LOC.name;WX.stamp=new Date().toLocaleTimeString('en-PH',{hour:'numeric',minute:'2-digit'});wxLive=true;
if(manual)toast('Weather updated');if(role&&['dashboard','weather','admin'].includes(view)&&!document.querySelector('dialog[open]')&&!document.getElementById('cmd'))render()}catch(e){wxLive=false;if(manual)toast('Could not reach the live weather service. Showing the saved forecast.',3400)}}
loadWx();setInterval(loadWx,30*60*1000);
function adv(id){const c=S.crops.find(x=>x.id==id);c.stage++;save();toast(c.name+' is now in '+STAGES[c.stage]+' stage');render()}
function go(v){location.hash=v}
function notes(){const a=[];S.tasks.filter(t=>!t.done&&t.date<TODAY).forEach(t=>a.push(['late',t.type+' · '+cn(t.crop).name+' is overdue']));S.tasks.filter(t=>!t.done&&t.date==TODAY).forEach(t=>a.push(['warn',t.type+' · '+cn(t.crop).name+' today at '+(t.time||'any time')]));S.tasks.filter(t=>!t.done&&t.date==add(1)).forEach(t=>a.push(['',t.type+' · '+cn(t.crop).name+' tomorrow']));S.logs.filter(l=>l.health=='Problem').forEach(l=>a.push(['late',cn(l.crop).name+': '+(l.issue||'needs attention')]));S.inputs.filter(i=>i.qty<=i.min).forEach(i=>a.push(['late','Low stock: '+i.name+' ('+i.qty+' '+i.unit+' left)']));wxAlerts().slice(0,4).forEach(x=>a.push([x.lvl=='no'?'late':'warn','Weather: '+x.msg]));return a}
function loginView(){return `<div class="login"><div class="lv"><div class="brand"><div class="logo">${svg(P.Planting,20,2.4)}</div>Crop Care Scheduler</div><div><h1>Plan every task. <span>Finish every season strong.</span></h1><p style="margin-top:18px">Schedule crop care, track what is done, log harvests, and never miss a watering or spray again.</p></div><p style="font-size:13px;margin:0">Barangay Magtaking, San Carlos City, Pangasinan</p></div>
<div class="lf"><div class="fm"><h2>Sign in</h2><p style="color:var(--mute);margin:0">Use your farm account to continue.</p><label>Sign in as</label><div class="roles"><label><input type="radio" name="r" value="Farmer" checked>Farmer</label><label><input type="radio" name="r" value="Admin">Admin</label></div><label for="u">Username</label><input id="u" value="juan.delacruz" autocomplete="username"><label for="pw">Password</label><input id="pw" type="password" value="password" autocomplete="current-password"><button type="button" class="btn gold" onclick="signIn()">Sign in</button></div></div></div>`}
function render(){if(!role){$('#root').innerHTML=scr=='landing'?landingView():authView2(scr);if(scr=='landing'){reveal()}return}const h=location.hash.slice(1),nav=navFor();view=V[h]&&nav.some(n=>n[0]==h)?h:nav[0][0];const nt=notes();
$('#root').innerHTML=`<header><div class="brand"><div class="logo">${svg(P.Planting,20,2.4)}</div><span>Crop Care Scheduler</span></div><nav aria-label="Main">${nav.map(n=>`<a href="#${n[0]}" ${n[0]==view?'aria-current="page"':''}>${n[1]}</a>`).join('')}</nav>
<div class="hr"><button class="ib" aria-label="Quick search (Ctrl K)" title="Quick search (Ctrl+K)" onclick="openCmd()">${svg('M11 18a7 7 0 100-14 7 7 0 000 14zM21 21l-5-5',18)}</button><button class="ib" aria-label="Toggle dark mode" onclick="document.documentElement.dataset.theme=document.documentElement.dataset.theme=='dark'?'light':'dark'">${svg('M21 13A9 9 0 1111 3a7 7 0 0010 10z',18)}</button><button class="ib" aria-label="Notifications" onclick="$('#np').classList.toggle('on')">${svg('M18 8a6 6 0 10-12 0c0 7-3 9-3 9h18s-3-2-3-9M13.7 21a2 2 0 01-3.4 0',18)}${nt.length?`<span class="badge">${nt.length}</span>`:''}</button><button class="av" aria-label="Log out" title="Log out (${role})" onclick="role=null;scr='landing';render();window.scrollTo(0,0)">${role=='Admin'?'AD':UI}</button>
<div class="pop" id="np"><h3>Reminders</h3>${nt.length?nt.slice(0,7).map(n=>`<div class="nt"><span class="tag ${n[0]}">${n[0]=='late'?'Alert':n[0]=='warn'?'Today':'Soon'}</span><span>${n[1]}</span></div>`).join(''):'<div class="empty">No reminders.</div>'}</div></div></header><main>${V[view]()}</main><div class="afoot">Crop Care Scheduler · Barangay Magtaking · <a href="#" onclick="event.preventDefault();showTerms(true)">Terms of Use</a> · <a href="#" onclick="event.preventDefault();showTerms(true)">Data Privacy Notice</a></div>`;after()}
function signIn(){UN='Juan';UI='JD';const r=document.querySelector('input[name=r]:checked');role=r?r.value:'Farmer';location.hash='dashboard';render();window.scrollTo(0,0)}
addEventListener('keydown',e=>{if(!role&&e.key=='Enter'){if(scr=='login')doLogin();else if(scr=='signup')doSignup()}});
addEventListener('hashchange',render);render();
